public int marsExploration(String s) {
    String expected = "SOS".repeat(s.length() / 3);
    int changed = 0;
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) != expected.charAt(i)) {
            changed++;
        }
    }
    return changed;
}

